<template>
  <button :class="buttonClass">
    <slot></slot>
  </button>
</template>

<script>
export default {
  props: {
    type: {
      type: String,
      default: 'button'
    }
  },
  computed: {
    buttonClass() {
      switch (this.type) {
        case 'outline':
          return 'button button--outline';
        default:
          return 'button';
      }
    }
  }
};
</script>
